const form=document.querySelector('#loginForm'),email=document.querySelector('#email'),password=document.querySelector('#password'),toggle=document.querySelector('#passwordToggle'),feedback=document.querySelector('#loginFeedback');
function showError(input,message){const error=document.querySelector(`#${input.id}Error`);input.classList.toggle('input-error',Boolean(message));error.hidden=!message;error.textContent=message}
function validate(){let valid=true;showError(email,'');showError(password,'');if(!email.value.trim()){showError(email,'Ingresa tu correo electrónico.');valid=false}else if(!email.validity.valid){showError(email,'Revisa el formato de tu correo.');valid=false}if(!password.value){showError(password,'Ingresa tu contraseña.');valid=false}return valid}
toggle.addEventListener('click',()=>{const visible=password.type==='text';password.type=visible?'password':'text';toggle.setAttribute('aria-label',visible?'Mostrar contraseña':'Ocultar contraseña');toggle.setAttribute('aria-pressed',String(!visible))});
[email,password].forEach(input=>input.addEventListener('input',()=>{if(input.classList.contains('input-error'))validate()}));form.addEventListener('submit',event=>{event.preventDefault();feedback.textContent='';if(!validate())return;feedback.textContent='Acceso correcto. Abriendo productos…';setTimeout(()=>{window.location.href='products.html'},450)});
